import csv,hashlib,json,random
from collections import Counter,defaultdict
import numpy as np
from vs import refcorpus
raw=open('/tmp/voy-piii.csv','rb').read();assert hashlib.sha256(raw).hexdigest()=='fe3f24a46dbc6b655eab8dbbd75addf84ee4a7dbd387ad802af75d02edfe5b4d'
table=list(csv.DictReader(raw.decode('utf-8-sig').splitlines()));alphabet=list(table[0]);allowed=set(alphabet)
for row in table:
 for c in row:row[c]=row[c].strip()
BOOKS=('la_augustine','es_lucanor','de_nibelunge');SEEDS=(1103,2207,3301);PERIODS=(10,24,131);MODES=('cyclic','noise2','gap1','phasejump','random','repeat10','markov')
def score(a,lag):return float(np.mean(a[:-lag]==a[lag:]))
def infer(a,seed):
 rates=np.array([score(a,k) for k in range(2,161)]);r=np.random.default_rng(seed);null=[]
 for j in range(49):
  b=r.permutation(a);null.append(max(score(b,k) for k in range(2,161)))
 sig=[i+2 for i,v in enumerate(rates) if (1+sum(n>=v for n in null))/50<=.05]
 return (min(sig) if sig else None),(1+sum(n>=max(rates) for n in null))/50

def test_lag(a,lag,seed):
 r=np.random.default_rng(seed);v=score(a,lag);null=[score(r.permutation(a),lag) for i in range(49)];return v,(1+sum(x>=v for x in null))/50

def markov(ref,seed,n):
 r=random.Random(seed);cnt=Counter(zip(ref,ref[1:]));rows=defaultdict(list)
 for a in alphabet:rows[a]=[cnt[a,b]+1 for b in alphabet]
 x=[r.choice(alphabet)]
 for i in range(n-1):x.append(r.choices(alphabet,weights=rows[x[-1]],k=1)[0])
 return ''.join(x)
def make(plain,period,mode,seed):
 r=random.Random(seed);rows=r.sample(range(len(table)),period);gate=random.Random(seed+777);noise=random.Random(seed+888);pos=0;out=[];valid=[]
 for i,c in enumerate(plain):
  if mode in ('random','repeat10','markov'):cidx=r.randrange(period)
  else:
   if i:
    if mode=='gap1' and gate.random()<.01:pass
    else:pos=(pos+1)%period
   if mode=='phasejump' and i==2000:pos=(pos+1)%period
   cidx=pos
  w=table[rows[cidx]][c]
  if mode=='noise2' and noise.random()<.02:
   k=noise.randrange(len(w));rep=noise.choice([x for x in 'abcdefghijklmnopqrstuvwxyz' if x!=w[k]]);w=w[:k]+rep+w[k+1:]
  out.append(w)
 codes={w:i for i,w in enumerate(sorted(set(out)))};return np.array([codes[w] for w in out],dtype=np.int32)
out={'books':BOOKS,'periods':PERIODS,'seeds':SEEDS,'modes':MODES,'rows':[]}
for book in BOOKS:
 pin=next(x for x in refcorpus.pins() if x['id']==book);assert hashlib.sha256(open(pin['file'],'rb').read()).hexdigest()==pin['sha256'];plain=''.join(c for b in refcorpus.blocks_of(book) for c in b if c in allowed);assert len(plain)>=12000;ref=plain[:4000];test=plain[4000:12000]
 for period in PERIODS:
  for seed in SEEDS:
   for mode in MODES:
    use=test
    if mode=='repeat10':
     rr=random.Random(seed+55);motif=rr.choices(alphabet,k=10);use=''.join(motif[i%10] for i in range(8000))
    elif mode=='markov':use=markov(ref,seed+44,8000)
    arr=make(use,period,mode,seed);lag,p=infer(arr[:4000],seed+10000)
    ev,ep=(None,None) if lag is None else test_lag(arr[4000:],lag,seed+20000)
    out['rows'].append({'book':book,'period':period,'seed':seed,'mode':mode,'selected_lag':lag,'train_maxp':p,'eval_score':ev,'eval_fixed_lag_p':ep})
 print('done '+book,flush=True,file=__import__('sys').stderr)
print(json.dumps(out,indent=2))
